"""Git lab checker. Do not edit this file.

Run it from anywhere inside your repository:

    python tools/check.py

It checks each mission, prints your score, and writes submission.txt at the
root of your repository. Upload that file to Moodle. You can run it as many
times as you like; only the file you upload counts.
"""

import datetime
import re
import subprocess
import sys
import types
from pathlib import Path

MAIN = "main"
TOTAL = 20


# --------------------------------------------------------------------------- helpers

def git(*args, timeout=30):
    try:
        r = subprocess.run(["git", *args], cwd=ROOT, capture_output=True,
                           text=True, timeout=timeout, encoding="utf-8",
                           errors="replace")
        return r.stdout.strip(), r.returncode
    except (OSError, subprocess.TimeoutExpired):
        return "", 1


def out(*args, **kw):
    return git(*args, **kw)[0]


def find_root():
    here = Path(__file__).resolve().parent
    try:
        r = subprocess.run(["git", "rev-parse", "--show-toplevel"], cwd=here,
                           capture_output=True, text=True)
    except OSError:
        sys.exit("Git is not installed or not on your PATH.")
    if r.returncode != 0:
        sys.exit("This folder is not a Git repository. Did you clone it?")
    return Path(r.stdout.strip())


ROOT = find_root()


def show(path, ref=MAIN):
    text, code = git("show", f"{ref}:{path}")
    return text if code == 0 else None


def main_commits():
    fmt = "%H%x1f%P%x1f%ae%x1f%ce%x1f%s"
    text = out("log", MAIN, f"--format={fmt}")
    commits = []
    for line in text.splitlines():
        h, parents, ae, ce, subject = (line.split("\x1f") + [""] * 5)[:5]
        commits.append({"sha": h, "parents": parents.split(), "author": ae,
                        "committer": ce, "subject": subject})
    return commits


def load_module():
    src = show("ids_eval.py")
    if src is None:
        return None
    mod = types.ModuleType("ids_eval_main")
    try:
        exec(compile(src, "ids_eval.py", "exec"), mod.__dict__)
    except Exception:
        return None
    return mod


def passes(fn):
    try:
        fn()
        return True
    except Exception:
        return False


def t_precision(m):
    assert m.precision({"tp": 8, "fp": 2, "fn": 4, "tn": 16}) == 0.8
    assert m.precision({"tp": 0, "fp": 0, "fn": 3, "tn": 5}) == 0.0


def t_threshold(m):
    assert m.predict(0.9) == "attack"
    assert m.predict(0.5) == "attack"
    assert m.predict(0.49) == "normal"
    assert m.predict(0.95, threshold=0.95) == "attack"


def t_most_missed(m):
    flows = [
        {"label": "attack", "attack_type": "DoS", "attack_prob": 0.9},
        {"label": "attack", "attack_type": "DoS", "attack_prob": 0.2},
        {"label": "attack", "attack_type": "PortScan", "attack_prob": 0.1},
        {"label": "attack", "attack_type": "PortScan", "attack_prob": 0.3},
        {"label": "normal", "attack_type": "none", "attack_prob": 0.1},
    ]
    assert m.most_missed_attack(flows) == ("PortScan", 2)


def norm_url(url):
    url = url.strip().lower()
    url = re.sub(r"^git@github\.com:", "https://github.com/", url)
    url = re.sub(r"\.git$", "", url).rstrip("/")
    return url


# --------------------------------------------------------------------------- checks

def run_checks():
    results = []  # (mission, title, points, max, note)

    def add(num, title, pts, mx, note=""):
        results.append((num, title, pts, mx, note))

    if git("rev-parse", "--verify", MAIN)[1] != 0:
        sys.exit("No 'main' branch found in this repository.")

    commits = main_commits()
    subjects = [c["subject"] for c in commits]
    gb = load_module()
    readme = show("README.md") or ""
    main_py = show("main.py") or ""
    tracked = out("ls-tree", "-r", "--name-only", MAIN).splitlines()
    head_reflog = out("reflog", "--format=%gs", "-n", "500").splitlines()

    # 1. Fork, clone, upstream
    origin = norm_url(out("config", "--get", "remote.origin.url"))
    upstream = norm_url(out("config", "--get", "remote.upstream.url"))
    pts, note = 0, ""
    if "github.com" in origin:
        pts += 1
    else:
        note = "origin should be your fork on GitHub"
    if upstream and "github.com" in upstream and upstream != origin:
        pts += 1
    elif not note:
        note = "no remote named 'upstream' pointing to the teacher's repository"
    add(1, "Your own copy", pts, 2, note)

    # 2. First commit
    author = ""
    if "## Author" in readme:
        section = readme.split("## Author", 1)[1]
        lines = [l.strip() for l in section.splitlines()
                 if l.strip() and not l.strip().startswith("<!--")]
        author = lines[0] if lines else ""
    add(2, "Sign your work", 1 if author else 0, 1,
        "" if author else "your name is not under ## Author in README.md on main")

    # 3. Pull a change made on GitHub
    web = [c for c in commits if c["committer"] == "noreply@github.com"
           and len(c["parents"]) == 1
           and not c["subject"].startswith("Merge")]
    add(3, "A change made somewhere else", 2 if web else 0, 2,
        "" if web else "no commit made on the GitHub website is in your local main")

    # 4. Bug 1 + local merge
    pts, notes = 0, []
    if gb and passes(lambda: t_precision(gb)):
        pts += 1
    else:
        notes.append("precision() still wrong on main")
    if any(re.match(r"Merge branch '?fix/precision'?", s) for s in subjects):
        pts += 1
    else:
        notes.append("no merge commit of fix/precision found on main")
    add(4, "Bug 1, merged by you", pts, 2, "; ".join(notes))

    # 5. Bug 2 + pull request
    pts, notes = 0, []
    if gb and passes(lambda: t_threshold(gb)):
        pts += 1
    else:
        notes.append("predict() still wrong on main")
    if any(re.match(r"Merge pull request #\d+ from \S*fix/threshold", s)
           for s in subjects):
        pts += 1
    else:
        notes.append("no merged pull request from fix/threshold in your local main")
    add(5, "Bug 2, pull request", pts, 2, "; ".join(notes))

    # 6. Merge conflict from upstream
    pts, notes = 0, []
    title_commit = ""
    for line in out("log", "--all", "--format=%H%x1f%s").splitlines():
        h, _, s = line.partition("\x1f")
        if s == "Lower decision threshold to catch more attacks":
            title_commit = h
            break
    if title_commit and git("merge-base", "--is-ancestor", title_commit, MAIN)[1] == 0:
        pts += 1
    else:
        notes.append("your teammate's commit is not in main")
    markers = []
    for f in tracked:
        if f.endswith((".py", ".md", ".csv", ".txt")):
            text = show(f) or ""
            if re.search(r"^(<<<<<<< |=======$|>>>>>>> )", text, re.M):
                markers.append(f)
    compiles = True
    try:
        compile(main_py, "main.py", "exec")
    except SyntaxError:
        compiles = False
    one_threshold = len(re.findall(r"^THRESHOLD\s*=", main_py, re.M)) == 1
    if pts and not markers and compiles and one_threshold:
        pts += 1
    elif pts and not one_threshold:
        notes.append("main.py must set THRESHOLD exactly once")
    elif markers:
        notes.append("conflict markers left in: " + ", ".join(markers))
    elif not compiles:
        notes.append("main.py has a syntax error")
    add(6, "A teammate's work", pts, 2, "; ".join(notes))

    # 7. Revert
    pts, notes = 0, []
    if any(s.startswith('Revert "Add debug output"') for s in subjects):
        pts += 1
    else:
        notes.append("no commit on main undoes 'Add debug output'")
    if "DEBUG" not in main_py:
        pts += 1
    else:
        notes.append("the DEBUG line is still in main.py")
    add(7, "Undo a shared mistake", pts, 2, "; ".join(notes))

    # 8. Stash
    pts, notes = 0, []
    if "lab-stash" in out("stash", "list"):
        pts += 1
    else:
        notes.append("no stash named lab-stash in the stash list")
    if "detecton" not in readme.lower():
        pts += 1
    else:
        notes.append('README title typo "Detecton" not fixed on main')
    add(8, "Interrupted", pts, 2, "; ".join(notes))

    # 9. Rebase + fast-forward
    pts, notes = 0, []
    branch_ok = git("rev-parse", "--verify", "fix/most-missed")[1] == 0
    merged = branch_ok and git("merge-base", "--is-ancestor",
                               "fix/most-missed", MAIN)[1] == 0
    if gb and passes(lambda: t_most_missed(gb)) and merged:
        pts += 1
    else:
        notes.append("fix/most-missed not fixed and merged into main")
    branch_reflog = out("reflog", "show", "--format=%gs",
                        "refs/heads/fix/most-missed") if branch_ok else ""
    if "rebase" in branch_reflog or any(
            "rebase" in l and "fix/most-missed" in l for l in head_reflog):
        pts += 1
    else:
        notes.append("fix/most-missed was not moved on top of main")
    add(9, "Catch up with main", pts, 2, "; ".join(notes))

    # 10. Reset
    reset_used = any(l.startswith("reset: moving to") for l in head_reflog)
    oops_gone = "oops.txt" not in tracked and "oops.txt" not in out("ls-files")
    ok = reset_used and oops_gone
    add(10, "Undo a mistake nobody has seen", 1 if ok else 0, 1,
        "" if ok else ("oops.txt is still committed" if not oops_gone
                       else "the oops commit was never removed from history"))

    # 11. .gitignore
    gi = show(".gitignore") or ""
    ok = "__pycache__" in gi
    add(11, "Clean up and ship", 1 if ok else 0, 1,
        "" if ok else "nothing on main makes Git ignore __pycache__")

    # 12. Pushed
    git("fetch", "origin", "--quiet", timeout=30)
    local = out("rev-parse", MAIN)
    remote = out("rev-parse", f"origin/{MAIN}")
    ok = local and local == remote
    add(12, "Everything published", 1 if ok else 0, 1,
        "" if ok else "your local main and the main on GitHub are different")

    # Bonus: tag
    bonus = 0
    if git("rev-parse", "-q", "--verify", "refs/tags/v1.0")[1] == 0:
        if out("ls-remote", "--tags", "origin", "v1.0", timeout=30):
            bonus = 1
    add("B", "Bonus: release v1.0", bonus, 0,
        "" if bonus else "optional: no v1.0 marker found on GitHub")

    return results, author


# --------------------------------------------------------------------------- report

def main():
    results, author = run_checks()
    score = sum(r[2] for r in results if r[0] != "B")
    bonus = sum(r[2] for r in results if r[0] == "B")
    lines = []
    for num, title, pts, mx, note in results:
        mark = "OK" if (pts == mx and mx) or (num == "B" and pts) else "--"
        label = f"+{pts}" if num == "B" else f"{pts}/{mx}"
        line = f"[{mark}] {str(num):>2}. {title:<44} {label:>5}"
        if note:
            line += f"\n          -> {note}"
        lines.append(line)
    table = "\n".join(lines)
    summary = f"SCORE: {score} / {TOTAL}" + (f"  (+{bonus} bonus)" if bonus else "")

    print(table)
    print("\n" + summary)

    def section(title, text):
        return f"\n\n===== {title} =====\n{text}"

    now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
    report = (
        "GIT LAB SUBMISSION\n"
        f"Student (README):  {author or '(missing)'}\n"
        f"Git user:          {out('config', 'user.name')} <{out('config', 'user.email')}>\n"
        f"Fork (origin):     {out('config', '--get', 'remote.origin.url')}\n"
        f"main is at:        {out('rev-parse', MAIN)}\n"
        f"Generated:         {now}\n\n"
        f"{table}\n\n{summary}"
        + section("REMOTES", out("remote", "-v"))
        + section("BRANCHES", out("branch", "-a", "-vv"))
        + section("STASH", out("stash", "list") or "(empty)")
        + section("HISTORY", out("log", "--graph", "--oneline", "--decorate",
                                 "--all", "-n", "80"))
        + section("REFLOG", out("reflog", "-n", "120"))
        + "\n"
    )
    path = ROOT / "submission.txt"
    path.write_text(report, encoding="utf-8")
    print(f"\nSubmission file written: {path}")
    print("Upload it to Moodle together with the URL of your fork.")


if __name__ == "__main__":
    main()
